mapper.select:
SELECT r.id AS room_id, r.number AS room_number, r.name AS room_name,
       o.id AS order_id, o.guest_name, o.guest_count, o.check_in, o.check_out,
       o.status AS order_status, c.name AS channel_name, b.id AS block_id
FROM room r
LEFT JOIN orders o
  ON o.room_id = r.id
 AND o.status <> #{cancelledStatus}
 AND o.check_in <= #{date}
 AND o.check_out > #{date}
LEFT JOIN channels c ON c.id = o.channel_id
LEFT JOIN room_block b
  ON b.room_id = r.id
 AND b.start_date <= #{date}
 AND b.end_date > #{date}
ORDER BY r.floor, r.number
